import subprocess,re,hashlib,json,os
root=Path(__file__).resolve().parents[1];cc=os.environ.get('HR_GTSTD_CC','/tmp/toolchain/bin/x86_64-w64-mingw32-gcc');src='runtime/hrgtstd.c';flags=['-D_WIN64','-std=c99','-O2','-S','-mabi=sysv','-ffreestanding','-fno-builtin','-fno-stack-protector','-fno-asynchronous-unwind-tables','-fno-unwind-tables','-fno-ident','-mno-red-zone','-fno-pic','-mno-sse','-mno-mmx','-fno-tree-vectorize','-mno-stack-arg-probe','-minline-all-stringops','-mstringop-strategy=rep_byte','-fno-jump-tables','-mno-push-args','-fcf-protection=none','-Wall','-Wextra','-Werror']
