 if not name.startswith('hbc_gtstd_') and name!='hbc_gtstd_render':s=re.sub(r'(?<![A-Za-z0-9_.])'+re.escape(name)+r'(?![A-Za-z0-9_.$])','hrgtstd_local_'+name,s)
